$result.stage='GENERATE';$g=Eval $w ([ref]$q) "(() => {const K=String.fromCharCode(49373,49457);const v=e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&!e.disabled&&String(e.getAttribute('aria-disabled')).toLowerCase()!=='true'};const roots=[...document.querySelectorAll('[role=dialog],mat-dialog-container,.mat-mdc-dialog-container')].filter(v);const root=roots[roots.length-1]||document;const all=[...root.querySelectorAll('button,[role=button]')].filter(v).map(e=>{const r=e.getBoundingClientRect(),m=String([e.innerText,e.textContent,e.getAttribute('aria-label'),e.getAttribute('title')].join(' ')).trim();return{e,r,m}});let a=all.filter(o=>{const t=o.m.toLowerCase();return o.m===K||o.m.startsWith(K+' ')||t==='generate'||t.startsWith('generate ')||t==='create'||t.startsWith('create ')});if(!a.length)return{ok:false,dump:all.map(o=>o.m).filter(Boolean).slice(-50)};const o=a[a.length-1],r=o.r;return{ok:true,x:r.left+r.width/2,y:r.top+r.height/2,text:o.m.slice(0,160)}})()";if(-not$g.ok){$result.controlDump=@($g.dump);throw 'GENERATE_CONTROL_NOT_FOUND'};$result.generateCandidate=[string]$g.text;Click $w ([ref]$q) $g.x $g.y;$result.generateClicked=$true;Start-Sleep -Seconds 3
